package com.learnspherex.payment;
import java.math.*; import java.time.*; import jakarta.validation.constraints.*;
public final class PaymentDtos { private PaymentDtos(){} public record InstallmentRequest(@Min(1) int number,@NotNull @DecimalMin("0.01") BigDecimal amount,@NotNull LocalDate dueDate){} public record CreateFeePlanRequest(@NotNull Long courseId,@NotBlank String name,@NotNull @DecimalMin("0.01") BigDecimal totalAmount,@NotEmpty java.util.List<InstallmentRequest> installments){} public record RecordPaymentRequest(@NotNull Long studentUserId,@NotNull Long installmentId,@NotNull @DecimalMin("0.01") BigDecimal amount,@NotNull PaymentMethod method,@NotBlank String transactionReference){} public record PaymentResponse(Long paymentId,String receiptNumber,Long studentUserId,Long installmentId,BigDecimal amount,PaymentMethod method,PaymentStatus status,String transactionReference,Instant paidAt){}
 public record OutstandingInstallment(Long installmentId,Long courseId,int installmentNumber,LocalDate dueDate,BigDecimal totalAmount,BigDecimal paidAmount,BigDecimal pendingAmount){}
 public record OutstandingSummary(Long studentUserId,java.util.List<OutstandingInstallment> installments,BigDecimal totalPending){} }
